const body = $json.body ?? $json;
const topic = typeof body.topic === 'string' ? body.topic.trim() : '';
const language = typeof body.language === 'string' ? body.language.trim().toLowerCase() : '';
const duration = Number(body.duration);
const errors = [];
if (!topic) errors.push('topic is required');
if (!['en','pl','ru','uk'].includes(language)) errors.push('language must be one of: en, pl, ru, uk');
if (![15,30,45,60].includes(duration)) errors.push('duration must be one of: 15, 30, 45, 60');
let jobId = null;
if (errors.length === 0) {
  if (globalThis.crypto?.randomUUID) jobId = globalThis.crypto.randomUUID();
  else {
    const h = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx';
    jobId = h.replace(/[xy]/g, c => { const r = Math.random()*16|0; const v = c === 'x' ? r : (r&0x3|0x8); return v.toString(16); });
  }
}
return [{json:{valid:errors.length===0, errors, jobId, topic, language, duration, inputPayload:{topic,language,duration}}}];
